-- rank 2801–2801
UPDATE words w SET
  definition_vi    = v.def_vi,
  part_of_speech   = v.pos,
  track            = v.track,
  is_function_word = v.is_func,
  needs_review     = v.review
FROM (VALUES
  ('dominate', 'thống trị, chi phối, áp đảo', 'Verb', 'Adult', FALSE, FALSE)
) AS v(term, def_vi, pos, track, is_func, review)
WHERE lower(w.term) = lower(v.term);


